(() => {
const search = document.querySelector("#search_courses_input").value;
document.querySelectorAll("div.courseInfo").forEach((e) => { if (!e.firstDescendant().firstDescendant().innerText.includes(search + ":")) {e.parentElement.remove()}});

document.querySelectorAll("div.courseAttributes").forEach((e) => { if (e.innerText.includes("Terms:")) {
const new_text = e.innerText.replace(/Terms: ([^\|]+)\|.*/, '$1');
e.parentElement.firstDescendant().firstDescendant().insertAdjacentHTML( 'afterend', `<span style="background-color: red;" class="courseNumber"> ${new_text} </span>` );
navigator.clipboard.writeText(new_text);
}});


window.data = [...document.querySelectorAll(".courseInfo")].map(info => {
const sectionContainerSel = ".sectionContainer";
const sectionContainerTermSel = ".sectionContainerTerm";
const sectionDetailsSel = ".sectionDetails";

return [...info.querySelectorAll(sectionContainerSel)].map(container => {
  const term = container.querySelector(sectionContainerTermSel).innerText;
  const details = container.querySelector(sectionDetailsSel);
  const yearRange = new RegExp(/\d{4}-\d{4}/);
  const dateRange = new RegExp(/\d\d\/\d\d\/\d\d\d\d - \d\d\/\d\d\/\d\d\d\d /);
  const instructors = new RegExp("with ([^;]+);([^;]+;)+")
  const no_schedule = new RegExp(/^-$/)
  const schedule = details.innerHTML.split("<br>")[1].trim().replace(dateRange, "").trim().replace(instructors, "with $1 ...").replace(no_schedule, "no schedule");


  return {element: info, term: term.replace(yearRange, ""), schedule};
})
})

for (const course of data) {
  for (const {element, term, schedule} of course) {
    const text = document.createElement("h2");
    text.style["font-size"] = "16px";
    text.style["background"] = "yellow";

    text.innerHTML = `${term}: ${schedule}`;
    element.firstChild.nextSibling.after(text);
  }
}

})()

(() => {
  const selectors = [
    ["https://explorecourses.stanford.edu.*", "#search_courses_input"],
    ["https://carta-beta.stanford.edu.*", "#downshift-0-input"],
    ["https://www.google.com/search.*", "input[aria-label=\"Search\"]"],
    ["https://search.brave.com/search.*", "#searchbox"],
    ["https://www.youtube.com/.*", "input#search"],
    ["https://en.cppreference.com/w/.*", "#p-search > form > input[type=search]:nth-child(2)"],
  ];
  for ([url_regex, selector] of selectors) {
    if (window.location.href.match(new RegExp(url_regex))) {
      const el = document.querySelector(selector);
      if (el) {
        el.focus();
        el.selectionStart = 0;
        el.selectionEnd = el.value.length;
        break;
      }
    }
  }

})()
